func TestLv7_LostReleaseReply(t *testing.T) {
	e := newEnv(t)
	a := MakeLock(e.clerk("C1"), "lock")
	b := MakeLock(e.clerk("C2"), "lock")
	within(t, 2*time.Second, "lock_stuck", say("加锁没有返回。", "Acquire did not return."), func() { a.Acquire() })
	e.net.Drop("C1", "rep", 4) // the reply to the Put that releases the lock
	within(t, 2*time.Second, "lock_stuck", say("解锁的 Put 执行了，但回复丢了。之后 Release 一直没有返回。", "The releasing Put ran but its reply was lost. Release then never returned."), func() { a.Release() })
	within(t, 2*time.Second, "lock_stuck", say("C1 解锁后，C2 一直拿不到锁。", "After C1 released, C2 never got the lock."), func() { b.Acquire() })
}

